export function findGroup(slug: string): CategoryGroup | undefined {
  return CATALOG.find(g => g.slug === slug);
}

export function findSub(catSlug: string, subSlug: string): SubCategory | undefined {
  return findGroup(catSlug)?.subs.find(s => s.slug === subSlug);
}

export function findProduct(catSlug: string, productSlug: string): Product | undefined {
  const g = findGroup(catSlug); if (!g) return;
  for (const s of g.subs) {
    const p = s.products.find(p => slugify(p.name) === productSlug);
    if (p) return p;
  }
}

export function slugify(s: string): string {
  return s.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
}